24	/** Blocks whose right-click runs a handler instead of placing the held block. */
25	export type InteractiveKind = "bed" | "furnace" | "chest" | "door";
26	
27	export const INTERACTIVE_BLOCKS: Partial<Record<BlockId, InteractiveKind>> = {
28	  [BlockId.Bed]: "bed",
29	  [BlockId.Furnace]: "furnace",
30	  [BlockId.Chest]: "chest",
31	  [BlockId.DoorNorthLower]: "door",
32	  [BlockId.DoorNorthUpper]: "door",
33	  [BlockId.DoorEastLower]: "door",
34	  [BlockId.DoorEastUpper]: "door",
35	  [BlockId.DoorSouthLower]: "door",
36	  [BlockId.DoorSouthUpper]: "door",
37	  [BlockId.DoorWestLower]: "door",
38	  [BlockId.DoorWestUpper]: "door",
39	  [BlockId.DoorNorthOpenLower]: "door",
40	  [BlockId.DoorNorthOpenUpper]: "door",
41	  [BlockId.DoorEastOpenLower]: "door",
42	  [BlockId.DoorEastOpenUpper]: "door",
43	  [BlockId.DoorSouthOpenLower]: "door",
44	  [BlockId.DoorSouthOpenUpper]: "door",
45	  [BlockId.DoorWestOpenLower]: "door",
46	  [BlockId.DoorWestOpenUpper]: "door"
47	};
