49	/**
50	 * Right-click "use" on the aimed block. Returns true when the click was an
51	 * interaction (consumed — the caller must NOT then place a block), false when
52	 * the aimed block has no behavior and placement should proceed.
53	 *
54	 * This is the shared hook future interactive blocks (furnace, …) plug into:
55	 * add a `BlockId → kind` entry and a branch below.
56	 */
57	export function tryInteractBlock(state: GameState, emit: EmitGameEvent): boolean {
58	  const { world, player } = state;
59	  scratchEye.set(player.position.x, player.position.y + EYE_HEIGHT, player.position.z);
60	  lookDirection(player.yaw, player.pitch, scratchDir);
61	  const result = voxelRaycast(world, scratchEye, scratchDir, MINE_REACH);
62	  if (!result) return false;
63	
64	  const block = world.get(result.hit.x, result.hit.y, result.hit.z) as BlockId;
65	  const kind = INTERACTIVE_BLOCKS[block];
66	  if (!kind) return false;
67	
68	  if (kind === "bed") return interactBed(state, emit, result.hit.x, result.hit.y, result.hit.z);
69	  if (kind === "furnace") return interactFurnace(state, emit);
70	  if (kind === "chest") return interactChest(state, emit, result.hit.x, result.hit.y, result.hit.z);
71	  if (kind === "door") return interactDoor(state, emit, result.hit.x, result.hit.y, result.hit.z);
72	  return false;
73	}
