  [BlockId.WheatStage0]: growCrop,
  [BlockId.WheatStage1]: growCrop,
  [BlockId.WheatStage2]: growCrop,
  // WheatStage3 has no handler — mature crops stop growing.
  [BlockId.Sapling]: growSapling
};

