    expect(max.find((d) => d.itemId === "seeds")!.count).toBe(2);
  });

  test("immature wheat returns just a seed", () => {
    expect(rollBlockDrops(BlockId.WheatStage1, () => 0.5)).toEqual([{ itemId: "seeds", count: 1 }]);
  });
});

