33	 * (skyExposure, blockLight). The scene's sun + hemisphere already scale with
34	 * daylight, so day/night needs no extra uniform and no re-mesh: this patch gates
35	 * the scene-lit color by sky exposure — caves go dark while the surface stays
36	 * lit and dims at night with the scene lights — then adds block light back as an
37	 * albedo-tinted glow that survives the gate, so a torch lights a pitch-black
38	 * cave. Anchored on stable ShaderChunk includes; the e2e triangle check guards
39	 * against a future Three.js bump breaking the string replace.
40	 */
41	function patchVoxelLighting(material: THREE.MeshStandardMaterial): void {
42	  material.onBeforeCompile = (shader) => {
43	    shader.vertexShader = "attribute vec2 aLight;\nvarying vec2 vLight;\n" + shader.vertexShader.replace("void main() {", "void main() {\n  vLight = aLight;");
44	    shader.fragmentShader =
45	      "varying vec2 vLight;\n" +
46	      shader.fragmentShader
47	        .replace("#include <color_fragment>", "#include <color_fragment>\n  vec3 mcAlbedo = diffuseColor.rgb;")
48	        .replace(
49	          "#include <opaque_fragment>",
50	          `#include <opaque_fragment>\n  gl_FragColor.rgb = gl_FragColor.rgb * max(vLight.x, ${SKY_LIGHT_FLOOR.toFixed(3)}) + mcAlbedo * vLight.y * ${TORCH_TINT};`
51	        );
52	  };
